package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorial
 */
public class MathUtils_factorial_TriageGen2Test {

    @Test
    public void testFactorial_Zero() {
        // 0! is 1
        assertEquals(1L, MathUtils.factorial(0));
    }

    @Test
    public void testFactorial_One() {
        // 1! is 1
        assertEquals(1L, MathUtils.factorial(1));
    }

    @Test
    public void testFactorial_SmallValue() {
        // 5! is 120
        assertEquals(120L, MathUtils.factorial(5));
    }

    @Test
    public void testFactorial_LargeValue() {
        // 20! is 2432902008176640000L
        // This is the largest factorial that fits in a signed long
        assertEquals(2432902008176640000L, MathUtils.factorial(20));
    }

    @Test(expected = ArithmeticException.class)
    public void testFactorial_Overflow() {
        // 21! exceeds Long.MAX_VALUE
        // Note: The implementation uses factorialDouble and checks if result == Long.MAX_VALUE
        // or if it's too large to fit. Since 21! is ~5.109e19 and Long.MAX_VALUE is ~9.223e18,
        // the Math.round(factorialDouble(21)) behavior or the subsequent check will trigger the exception.
        MathUtils.factorial(21);
    }

    @Test(expected = Exception.class)
    public void testFactorial_Negative() {
        // Factorial for negative numbers is typically undefined in this context 
        // and likely causes issues in factorialDouble or array access
        MathUtils.factorial(-1);
    }
}
